-- spa menu snapshots, batch 0 (25 menus)
with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'nikaraspa.com' and status = 'active' and publication_status = 'published' order by slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Nikara Spa Berawa treatment prices', 1, 'draft', 'partial', 'https://www.nikaraspa.com/nikara-spa-berawa-price', 'Official Nikara Spa Berawa price list',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '6f439b9a36e366b7f6b06c4bf195a7fafb1da043df706d94a068eb7a9d0514d9', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Balinese Massage', 0), ('Sound Healing', 1), ('Facial', 2), ('Spa Package', 3), ('Other', 4)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Balinese Massage', 'Balinese Harmony Healing Massage (90 min)', 'The ultimate introduction to Balinese wellness. Using traditional long strokes and palm pressure, this ritual balances your energy.', 590000, 'IDR', 0), ('Sound Healing', 'Sound Healing Massage (120 min)', 'A transformative experience that combines deep tissue work with the vibrational power of singing bowls.', 670000, 'IDR', 0), ('Facial', 'Vegan Hibiscus Vitamin C Brightening Facial (75 min)', 'A favorite for sun-kissed skin that needs a boost of antioxidants and hydration.', 500000, 'IDR', 0), ('Facial', 'Vegan Marigold Antioxidant Rejuvenation Facial (75 min)', 'Focuses on repairing the skin barrier and fighting the effects of pollution and UV exposure.', 500000, 'IDR', 1), ('Spa Package', 'Serenity Glow Package (120 min)', 'A combination of a full-body massage and a vegan organic facial.', 840000, 'IDR', 0), ('Spa Package', 'Healing Bliss Ritual (150 min)', 'An extended journey that includes a foot ritual, body scrub, signature massage, and a luxurious flower bath.', 1020000, 'IDR', 1), ('Other', 'Ultimate Self-Gratitude Retreat (210 min)', 'A 3.5-hour retreat that includes every element of the Nikara experience.', 1800000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

