  select m.id, s.name, s.pos from m, (values ('Deep Tissue', 0), ('Balinese Massage', 1), ('Traditional Massage', 2), ('Shiatsu', 3), ('Sports Massage', 4), ('Reflexology', 5), ('Thai Massage', 6), ('Neck & Shoulder', 7), ('Pregnancy Massage', 8), ('Other', 9), ('Cupping', 10), ('Facial', 11), ('Manicure', 12), ('Pedicure', 13), ('Ear Candle', 14), ('Balinese Boreh', 15), ('Javanese Lulur', 16), ('Body Scrub', 17), ('Reiki', 18), ('Spa Package', 19)) as s(name, pos)
  returning id, name
