join (values ('Other', 'Signature Treatments', 'Premium Jaens Spa experiences, including signature massage rituals, bamboo massage, and 4 hands massage for guests who want something more memorable than a standard massage.', 855000, 'IDR', 0), ('Other', 'Body Care', 'Refresh your skin with body scrub, body mask, body massage, and Balinese-inspired body rituals for smoother-feeling skin and deeper relaxation.', 845000, 'IDR', 1), ('Other', 'Beauty Care', 'Facial and beauty care treatments designed to cleanse, hydrate, and refresh tired skin after travel, tropical heat, and outdoor activities in Bali.', 375000, 'IDR', 2), ('Other', 'Hair Care', 'Hair spa, creambath, hair wash, hair mask, and scalp care treatments to help your hair and scalp feel clean, soft, and refreshed.', 275000, 'IDR', 3), ('Spa Package', 'Spa Packages', 'Complete spa journeys that combine massage, body care, facial, hair care, bath rituals, and refreshments for couples, travelers, and wellness seekers.', 1235000, 'IDR', 0), ('Spa Package', 'Jet Lag Massage Package (45 min)', null, 200000, 'IDR', 1), ('Traditional Massage', 'Body Massage', 'Relax your body with Balinese massage, deep tissue, aromatherapy, foot therapy, and focused massage treatments designed for tired muscles and travel fatigue.', 395000, 'IDR', 0), ('Balinese Massage', 'Traditional Balinese Massage (60 min)', null, 250000, 'IDR', 0), ('Hot Stone', 'Hot Stone Massage (60 min)', null, 300000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

